"""Backend tool registry for the assistant.

Rules enforced here, independent of what the model says:
* Arguments are validated with Pydantic before anything runs.
* The tenant (business_id) comes from the authenticated session, never from model arguments.
* "write" tools only produce a preview + pending AIAction; execution happens after the user confirms.
* Tools call the same deterministic services as the REST API. No SQL is ever generated by the model.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass
from decimal import Decimal
from typing import Any, Callable, Literal

from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator, model_validator
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.core.config import Settings
from app.core.errors import NotFound, ValidationFailed
from app.models import Business, Product, Profile, Sale
from app.models.entities import UNITS
from app.services import analytics as analytics_svc
from app.services import categories as categories_svc
from app.services import inventory as inventory_svc
from app.services import products as products_svc
from app.services import sales as sales_svc
from app.services.common import CENT, money_str, qty_str
from app.services.lexicon import UNIT_LABEL_AZ, fold, parse_unit

Unit = Literal["piece", "m2", "m", "m3", "kg", "ton", "l", "pack", "set"]
CURRENCY_SIGN = {"AZN": "₼", "USD": "$", "EUR": "€", "TRY": "₺", "RUB": "₽", "GBP": "£"}


@dataclass
class ToolContext:
    db: Session
    settings: Settings
    user: Profile
    business: Business
    conversation_id: uuid.UUID

    @property
    def business_id(self) -> uuid.UUID:
        return self.business.id

    @property
    def sign(self) -> str:
        return CURRENCY_SIGN.get(self.business.currency, self.business.currency)


class Args(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)


def _coerce_unit(v: Any) -> Any:
    if isinstance(v, str) and v not in UNITS:
        return parse_unit(v) or v
    return v


# ---------------------------------------------------------------------------
# Argument schemas
# ---------------------------------------------------------------------------
class CreateProductArgs(Args):
    name: str = Field(min_length=2, max_length=200, description="Product name in the user's language, e.g. 'Taxta qapı'")
    quantity: Decimal = Field(default=Decimal(0), ge=0, le=Decimal("1e9"), description="Units in stock")
    unit: Unit = Field(default="piece", description="Unit of measure")
    selling_price: Decimal | None = Field(default=None, ge=0, le=Decimal("1e9"), description="Selling price per unit")
    purchase_price: Decimal | None = Field(default=None, ge=0, le=Decimal("1e9"), description="Purchase/cost price per unit")
    category: str | None = Field(default=None, max_length=120, description="Category name; created if it does not exist")
    description: str | None = Field(default=None, max_length=2000)
    sku: str | None = Field(default=None, max_length=64)
    low_stock_threshold: int | None = Field(default=None, ge=0, le=1_000_000)
    merge_into_product_id: uuid.UUID | None = Field(
        default=None, description="If set, add the quantity to this existing product instead of creating a new one")

    coerce_unit = field_validator("unit", mode="before")(_coerce_unit)


class UpdateProductArgs(Args):
    product: str = Field(min_length=1, max_length=200, description="Existing product name, SKU or id")
    name: str | None = Field(default=None, min_length=2, max_length=200)
    description: str | None = Field(default=None, max_length=2000)
    category: str | None = Field(default=None, max_length=120)
    unit: Unit | None = None
    low_stock_threshold: int | None = Field(default=None, ge=0, le=1_000_000)

    coerce_unit = field_validator("unit", mode="before")(_coerce_unit)

    @model_validator(mode="after")
    def _something(self):
        if not any(getattr(self, f) is not None for f in ("name", "description", "category", "unit", "low_stock_threshold")):
            raise ValueError("at least one field to change is required")
        return self


class UpdateInventoryArgs(Args):
    product: str = Field(min_length=1, max_length=200, description="Existing product name, SKU or id")
    change: Decimal | None = Field(default=None, ge=-Decimal("1e9"), le=Decimal("1e9"), description="Signed quantity change, e.g. -40 to reduce by 40")
    set_quantity: Decimal | None = Field(default=None, ge=0, le=Decimal("1e9"), description="Set the stock to an absolute quantity")
    expected_version: int | None = None
    reason: str | None = Field(default=None, max_length=300)

    @model_validator(mode="after")
    def _one_of(self):
        if (self.change is None) == (self.set_quantity is None):
            raise ValueError("provide exactly one of change or set_quantity")
        if self.change is not None and self.change == 0:
            raise ValueError("change must not be zero")
        return self


class UpdatePriceArgs(Args):
    product: str = Field(min_length=1, max_length=200, description="Existing product name, SKU or id")
    selling_price: Decimal | None = Field(default=None, ge=0, le=Decimal("1e9"))
    purchase_price: Decimal | None = Field(default=None, ge=0, le=Decimal("1e9"))

    @model_validator(mode="after")
    def _one(self):
        if self.selling_price is None and self.purchase_price is None:
            raise ValueError("selling_price or purchase_price is required")
        return self


class RecordSaleArgs(Args):
    product: str = Field(min_length=1, max_length=200, description="Existing product name, SKU or id")
    quantity: Decimal = Field(gt=0, le=Decimal("1e9"), description="Units sold")
    unit_price: Decimal | None = Field(default=None, ge=0, le=Decimal("1e9"),
                                       description="Price per unit the user stated. Omit if not stated (the product's "
                                                   "recorded selling price is proposed, never an invented one)")
    customer_name: str | None = Field(default=None, max_length=200)
    note: str | None = Field(default=None, max_length=500)


class CancelSaleArgs(Args):
    sale_number: str = Field(min_length=3, max_length=30, description="Sale number, e.g. S-000012")
    reason: str | None = Field(default=None, max_length=300)


class SearchInventoryArgs(Args):
    query: str | None = Field(default=None, max_length=200)
    stock_status: Literal["low", "out", "in", "attention"] | None = None
    max_quantity: Decimal | None = Field(default=None, ge=0, description="Only products with quantity strictly below this")
    limit: int = Field(default=20, ge=1, le=100)


class EmptyArgs(Args):
    pass


class SalesAnalyticsArgs(Args):
    metric: Literal["summary", "top_revenue", "top_units", "unsold"] = "summary"
    days: int = Field(default=30, ge=1, le=365)
    limit: int = Field(default=10, ge=1, le=50)
    period: Literal["today", "this_week", "this_month", "last_month"] | None = None
    compare: bool = False


class ReorderArgs(Args):
    days: int = Field(default=30, ge=7, le=365, description="Sales history window used for sales velocity")


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def resolve_product(ctx: ToolContext, ref: str) -> Product:
    """Resolve a product reference strictly inside the caller's business."""
    db, bid = ctx.db, ctx.business_id
    try:
        pid = uuid.UUID(ref)
        return products_svc.get_product(db, bid, pid)
    except ValueError:
        pass
    p = db.scalar(select(Product).where(Product.business_id == bid, Product.sku == ref.strip(), Product.is_archived.is_(False)))
    if p:
        return products_svc.get_product(db, bid, p.id)
    exact = [p for p in db.scalars(select(Product).where(Product.business_id == bid, Product.is_archived.is_(False),
                                                         Product.name.ilike(ref.strip()))).all()]
    exact = exact or [p for p in db.scalars(select(Product).where(Product.business_id == bid,
                                                                  Product.is_archived.is_(False))).all()
                      if fold(p.name) == fold(ref)]
    if len(exact) == 1:
        return products_svc.get_product(db, bid, exact[0].id)
    matches = products_svc.find_matching_products(db, bid, ref, limit=3)
    if not matches:
        raise NotFound(f"“{ref}” adlı məhsul inventarınızda tapılmadı", code="product_not_found")
    if len(matches) > 1 and matches[0][1] - matches[1][1] < 0.1:
        names = ", ".join(f"{m.name} ({m.sku})" for m, _ in matches)
        raise ValidationFailed(f"Bir neçə uyğun məhsul var: {names}. Hansını nəzərdə tutursunuz?",
                               code="ambiguous_product", details={"candidates": [str(m.id) for m, _ in matches]})
    return products_svc.get_product(db, bid, matches[0][0].id)


def _product_row(p: Product) -> dict:
    s = products_svc.serialize_product(p)
    return {k: s[k] for k in ("id", "sku", "name", "quantity", "unit", "selling_price", "purchase_price",
                              "stock_status", "inventory_value", "low_stock_threshold")} | {
        "category": (s["category"] or {}).get("name")}


def _fmt_qty(q: Decimal | None, unit: str) -> str:
    return f"{qty_str(q)} {UNIT_LABEL_AZ.get(unit, unit)}"


def _fmt_money(ctx: ToolContext, m: Decimal | None) -> str:
    return f"{money_str(m)} {ctx.sign}" if m is not None else "—"


def _find_sale(ctx: ToolContext, number: str) -> Sale:
    s = ctx.db.scalar(select(Sale).where(Sale.business_id == ctx.business_id, Sale.number == number.strip().upper()))
    if s is None:
        raise NotFound(f"{number} nömrəli satış tapılmadı", code="sale_not_found")
    return sales_svc.get_sale(ctx.db, ctx.business_id, s.id)


# ---------------------------------------------------------------------------
# Write tools: preview + commit
# ---------------------------------------------------------------------------
def preview_create_product(ctx: ToolContext, a: CreateProductArgs) -> dict:
    warnings = []
    if a.quantity == 0:
        warnings.append("Miqdar göstərilməyib (0).")
    matches = []
    if a.merge_into_product_id:
        p = products_svc.get_product(ctx.db, ctx.business_id, a.merge_into_product_id)
        matches = [{"id": str(p.id), "name": p.name, "sku": p.sku, "quantity": qty_str(p.inventory.quantity), "unit": p.unit,
                    "score": 1.0}]
    else:
        for p, score in products_svc.find_matching_products(ctx.db, ctx.business_id, a.name, limit=3):
            matches.append({"id": str(p.id), "name": p.name, "sku": p.sku,
                            "quantity": qty_str(p.inventory.quantity if p.inventory else 0), "unit": p.unit, "score": score})
        if matches:
            warnings.append(f"İnventarınızda oxşar məhsul var: {matches[0]['name']}. Yeni məhsul yaratmaq əvəzinə "
                            "mövcud məhsula əlavə edə bilərsiniz.")
    fields = [
        {"key": "name", "label": "Məhsul", "value": a.name},
        {"key": "quantity", "label": "Miqdar", "value": qty_str(a.quantity)},
        {"key": "unit", "label": "Vahid", "value": a.unit},
        {"key": "selling_price", "label": f"Satış qiyməti ({ctx.sign})", "value": money_str(a.selling_price)},
        {"key": "purchase_price", "label": f"Alış qiyməti ({ctx.sign})", "value": money_str(a.purchase_price)},
    ]
    if a.category:
        fields.append({"key": "category", "label": "Kateqoriya", "value": a.category})
    return {
        "title": "Yeni məhsul" if not a.merge_into_product_id else "Mövcud məhsula əlavə",
        "summary": f"{a.name}: {_fmt_qty(a.quantity, a.unit)}",
        "fields": fields,
        "editable": ["name", "quantity", "unit", "selling_price", "purchase_price"] if not a.merge_into_product_id
        else ["quantity", "selling_price", "purchase_price"],
        "warnings": warnings,
        "matches": matches,
        # prices are optional: a product can be created now and priced later, nothing is guessed
        "missing": [],
    }


def commit_create_product(ctx: ToolContext, a: CreateProductArgs, action_id: uuid.UUID) -> dict:
    if a.merge_into_product_id:
        p = products_svc.get_product(ctx.db, ctx.business_id, a.merge_into_product_id)
        if a.quantity > 0:
            inventory_svc.adjust_stock(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id, product_id=p.id,
                                       delta=a.quantity, source="ai", ai_action_id=action_id, reason="AI köməkçi ilə əlavə")
        fields = {}
        if a.selling_price is not None:
            fields["selling_price"] = a.selling_price
        if a.purchase_price is not None:
            fields["purchase_price"] = a.purchase_price
        if fields:
            products_svc.update_product(ctx.db, actor_id=ctx.user.id, product=p, data=fields, via="ai")
        ctx.db.refresh(p)
        return {"product": _product_row(p), "merged": True}
    data: dict[str, Any] = {"name": a.name, "unit": a.unit, "selling_price": a.selling_price,
                            "purchase_price": a.purchase_price, "description": a.description, "sku": a.sku}
    if a.category:
        data["category_id"] = categories_svc.get_or_create(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id,
                                                           name=a.category, via="ai").id
    if a.low_stock_threshold is not None:
        data["low_stock_threshold"] = a.low_stock_threshold
    p = products_svc.create_product(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id, data=data,
                                    initial_quantity=a.quantity, via="ai", ai_action_id=action_id)
    p = products_svc.get_product(ctx.db, ctx.business_id, p.id)
    return {"product": _product_row(p), "merged": False}


def preview_update_product(ctx: ToolContext, a: UpdateProductArgs) -> dict:
    p = resolve_product(ctx, a.product)
    fields = [{"key": "product", "label": "Məhsul", "value": f"{p.name} ({p.sku})"}]
    for key, label in (("name", "Yeni ad"), ("description", "Təsvir"), ("category", "Kateqoriya"), ("unit", "Vahid"),
                       ("low_stock_threshold", "Minimum stok həddi")):
        v = getattr(a, key)
        if v is not None:
            fields.append({"key": key, "label": label, "value": str(v)})
    return {"title": "Məhsulu yenilə", "summary": p.name, "fields": fields, "warnings": [], "product_id": str(p.id)}


def commit_update_product(ctx: ToolContext, a: UpdateProductArgs, action_id: uuid.UUID) -> dict:
    p = resolve_product(ctx, a.product)
    data: dict[str, Any] = {k: getattr(a, k) for k in ("name", "description", "unit", "low_stock_threshold")
                            if getattr(a, k) is not None}
    if a.category:
        data["category_id"] = categories_svc.get_or_create(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id,
                                                           name=a.category, via="ai").id
    products_svc.update_product(ctx.db, actor_id=ctx.user.id, product=p, data=data, via="ai")
    return {"product": _product_row(p)}


def preview_update_inventory(ctx: ToolContext, a: UpdateInventoryArgs) -> dict:
    p = resolve_product(ctx, a.product)
    before = Decimal(p.inventory.quantity)
    after = a.set_quantity if a.set_quantity is not None else before + a.change
    warnings = []
    if after < 0:
        warnings.append(f"Stok kifayət etmir: mövcud {_fmt_qty(before, p.unit)}. Bu əməliyyat icra oluna bilməz.")
    return {
        "title": "Stoku yenilə",
        "summary": f"{p.name}: {qty_str(before)} → {qty_str(after)}",
        "fields": [
            {"key": "product", "label": "Məhsul", "value": f"{p.name} ({p.sku})"},
            {"key": "before", "label": "Hazırkı miqdar", "value": _fmt_qty(before, p.unit)},
            {"key": "after", "label": "Yeni miqdar", "value": _fmt_qty(after, p.unit)},
            {"key": "reason", "label": "Səbəb", "value": a.reason or "—"},
        ],
        "warnings": warnings,
        "blocked": after < 0,
        "product_id": str(p.id),
        "expected_version": p.inventory.version,
    }


def commit_update_inventory(ctx: ToolContext, a: UpdateInventoryArgs, action_id: uuid.UUID) -> dict:
    p = resolve_product(ctx, a.product)
    ev = inventory_svc.adjust_stock(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id, product_id=p.id,
                                    delta=a.change, set_to=a.set_quantity, reason=a.reason or "AI köməkçi",
                                    source="ai", ai_action_id=action_id, expected_version=a.expected_version)
    ctx.db.refresh(p)
    return {"product": _product_row(p), "event": inventory_svc.serialize_event(ev, p.name, p.unit)}


def preview_update_price(ctx: ToolContext, a: UpdatePriceArgs) -> dict:
    p = resolve_product(ctx, a.product)
    fields = [{"key": "product", "label": "Məhsul", "value": f"{p.name} ({p.sku})"}]
    if a.selling_price is not None:
        fields.append({"key": "selling_price", "label": "Satış qiyməti",
                       "value": f"{_fmt_money(ctx, p.selling_price)} → {_fmt_money(ctx, a.selling_price)}"})
    if a.purchase_price is not None:
        fields.append({"key": "purchase_price", "label": "Alış qiyməti",
                       "value": f"{_fmt_money(ctx, p.purchase_price)} → {_fmt_money(ctx, a.purchase_price)}"})
    warnings = []
    sp = a.selling_price if a.selling_price is not None else p.selling_price
    pp = a.purchase_price if a.purchase_price is not None else p.purchase_price
    if sp is not None and pp is not None and sp < pp:
        warnings.append("Satış qiyməti alış qiymətindən aşağıdır.")
    return {"title": "Qiyməti yenilə", "summary": p.name, "fields": fields, "warnings": warnings, "product_id": str(p.id)}


def commit_update_price(ctx: ToolContext, a: UpdatePriceArgs, action_id: uuid.UUID) -> dict:
    p = resolve_product(ctx, a.product)
    data = {k: getattr(a, k) for k in ("selling_price", "purchase_price") if getattr(a, k) is not None}
    products_svc.update_product(ctx.db, actor_id=ctx.user.id, product=p, data=data, via="ai")
    return {"product": _product_row(p)}


def preview_record_sale(ctx: ToolContext, a: RecordSaleArgs) -> dict:
    p = resolve_product(ctx, a.product)
    available = Decimal(p.inventory.quantity)
    price = a.unit_price if a.unit_price is not None else p.selling_price
    warnings, missing = [], []
    if a.unit_price is None and p.selling_price is not None:
        warnings.append(f"Qiymət deyilmədi: məhsulun qeydə alınmış satış qiyməti götürüldü ({_fmt_money(ctx, p.selling_price)}). "
                        "Fərqli qiymətə satılıbsa, kartda düzəldin.")
    if price is None:
        missing.append("unit_price")
        warnings.append("Satış qiyməti məlum deyil. Təsdiqdən əvvəl hər vahidin qiymətini daxil edin.")
    if a.quantity > available:
        warnings.append(f"Stok kifayət etmir: mövcud {_fmt_qty(available, p.unit)}, satış {_fmt_qty(a.quantity, p.unit)}. "
                        "Satış qeydə alına bilməz.")
    if p.purchase_price is None:
        warnings.append("Bu məhsulun alış qiyməti qeyd olunmayıb: satışın mənfəəti hesablanmayacaq.")
    total = (a.quantity * Decimal(price)).quantize(CENT) if price is not None else None
    fields = [
        {"key": "product", "label": "Məhsul", "value": f"{p.name} ({p.sku})"},
        {"key": "quantity", "label": "Miqdar", "value": qty_str(a.quantity)},
        {"key": "unit_price", "label": f"Vahid qiyməti ({ctx.sign})", "value": money_str(price)},
        {"key": "total", "label": "Cəmi", "value": _fmt_money(ctx, total)},
        {"key": "stock", "label": "Stok", "value": f"{_fmt_qty(available, p.unit)} → {_fmt_qty(available - a.quantity, p.unit)}"},
    ]
    if a.customer_name:
        fields.append({"key": "customer_name", "label": "Müştəri", "value": a.customer_name})
    return {
        "title": "Satışı qeydə al",
        "summary": f"{p.name}: {_fmt_qty(a.quantity, p.unit)} × {_fmt_money(ctx, price)} = {_fmt_money(ctx, total)}",
        "fields": fields,
        "editable": ["quantity", "unit_price", "customer_name"],
        "warnings": warnings,
        "missing": missing,
        "blocked": a.quantity > available,
        "product_id": str(p.id),
        "total": money_str(total),
    }


def commit_record_sale(ctx: ToolContext, a: RecordSaleArgs, action_id: uuid.UUID) -> dict:
    p = resolve_product(ctx, a.product)
    s = sales_svc.record_sale(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id,
                              items=[{"product_id": p.id, "quantity": a.quantity, "unit_price": a.unit_price}],
                              customer_name=a.customer_name, note=a.note, source="ai", ai_action_id=action_id,
                              idempotency_key=f"ai:{action_id}")
    ctx.db.refresh(p)
    return {"sale": {"id": str(s.id), "number": s.number, "total": money_str(s.total)}, "product": _product_row(p)}


def preview_cancel_sale(ctx: ToolContext, a: CancelSaleArgs) -> dict:
    s = _find_sale(ctx, a.sale_number)
    if s.kind != "sale":
        raise ValidationFailed("Bu qaytarma qeydidir, satış deyil", code="not_a_sale")
    returned = sales_svc.returned_quantities(ctx.db, s)
    lines = [(i, Decimal(i.quantity) - returned.get(i.id, Decimal(0))) for i in s.items]
    lines = [(i, q) for i, q in lines if q > 0]
    if not lines:
        raise ValidationFailed(f"{s.number} artıq tam qaytarılıb", code="already_returned")
    amount = sum(((q * Decimal(i.unit_price)).quantize(CENT) for i, q in lines), Decimal(0))
    return {
        "title": "Satışı ləğv et",
        "summary": f"{s.number}: {_fmt_money(ctx, amount)} geri qaytarılacaq",
        "fields": [{"key": "sale", "label": "Satış", "value": s.number},
                   *({"key": f"line{n}", "label": i.name, "value": f"+{_fmt_qty(q, i.unit)} stoka qayıdır"}
                     for n, (i, q) in enumerate(lines)),
                   {"key": "amount", "label": "Qaytarılan məbləğ", "value": _fmt_money(ctx, amount)},
                   {"key": "reason", "label": "Səbəb", "value": a.reason or "—"}],
        "warnings": ["Satış silinmir: ləğv ayrıca qaytarma qeydi kimi yazılır və stok geri artırılır."],
    }


def commit_cancel_sale(ctx: ToolContext, a: CancelSaleArgs, action_id: uuid.UUID) -> dict:
    s = _find_sale(ctx, a.sale_number)
    r = sales_svc.return_sale(ctx.db, actor_id=ctx.user.id, business_id=ctx.business_id, sale_id=s.id, items=None,
                              reason=a.reason or "AI köməkçi ilə ləğv", source="ai", ai_action_id=action_id,
                              idempotency_key=f"ai:{action_id}")
    return {"return": {"id": str(r.id), "number": r.number, "total": money_str(r.total)}, "sale_number": s.number}


# ---------------------------------------------------------------------------
# Read tools: return (result for the model, UI block)
# ---------------------------------------------------------------------------
def run_search_inventory(ctx: ToolContext, a: SearchInventoryArgs) -> tuple[dict, dict]:
    items, total = products_svc.list_products(ctx.db, ctx.business_id, q=a.query, stock=a.stock_status,
                                              page_size=500 if a.max_quantity is not None else a.limit, sort="quantity")
    if a.max_quantity is not None:
        items = [p for p in items if p.inventory and Decimal(p.inventory.quantity) < a.max_quantity]
        total = len(items)
    rows = [_product_row(p) for p in items[: a.limit]]
    title = "Axtarış nəticələri"
    if a.max_quantity is not None:
        title = f"{qty_str(a.max_quantity)} vahiddən az qalan məhsullar"
    elif a.stock_status in ("low", "attention"):
        title = "Stoku az olan məhsullar"
    elif not a.query:
        title = "İnventar"
    return {"total": total, "items": rows}, {"type": "inventory_table", "title": title, "total": total, "items": rows}


def run_inventory_summary(ctx: ToolContext, a: EmptyArgs) -> tuple[dict, dict]:
    s = inventory_svc.summary(ctx.db, ctx.business_id)
    return {**s, "currency": ctx.business.currency}, {"type": "inventory_summary", "data": s}


def run_sales_analytics(ctx: ToolContext, a: SalesAnalyticsArgs) -> tuple[dict, dict]:
    period = analytics_svc.resolve_period(ctx.business, days=a.days)
    if a.period:
        from datetime import timedelta
        today = analytics_svc.utc_now().astimezone(period.tz).date()
        start, end = today, today
        if a.period == "this_week":
            start = today - timedelta(days=today.weekday())
        elif a.period == "this_month":
            start = today.replace(day=1)
        elif a.period == "last_month":
            end = today.replace(day=1) - timedelta(days=1)
            start = end.replace(day=1)
        period = analytics_svc.resolve_period(ctx.business, date_from=start, date_to=end)
    if a.metric == "unsold":
        items = analytics_svc.unsold_products(ctx.db, ctx.business, period, limit=a.limit)
        data = {"metric": "unsold", "days": a.days, "items": items}
        return data, {"type": "analytics", "data": data}
    report = analytics_svc.sales_report(ctx.db, ctx.business, period, top_limit=a.limit)
    items = report["top_by_units"] if a.metric == "top_units" else report["top_by_revenue"]
    data = {"metric": a.metric, "days": period.days, "period": report["period"], "currency": ctx.business.currency, "totals": report["totals"],
            "items": items if a.metric != "summary" else report["top_by_revenue"][:5]}
    if a.compare:
        from datetime import timedelta
        end = period.start.replace(day=1) - timedelta(days=1)
        previous = analytics_svc.resolve_period(ctx.business, date_from=end.replace(day=1), date_to=end)
        data["previous_period"] = analytics_svc.sales_report(ctx.db, ctx.business, previous)["totals"]
    return data, {"type": "analytics", "data": data}


def run_reorder(ctx: ToolContext, a: ReorderArgs) -> tuple[dict, dict]:
    data = analytics_svc.reorder_suggestions(ctx.db, ctx.business, days=a.days)
    return data, {"type": "reorder", "data": data}


# ---------------------------------------------------------------------------
# Registry
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class ToolSpec:
    name: str
    description: str
    args_model: type[Args]
    kind: Literal["read", "write"]
    run: Callable[..., tuple[dict, dict]] | None = None
    preview: Callable[..., dict] | None = None
    commit: Callable[..., dict] | None = None

    def openai_schema(self) -> dict:
        schema = self.args_model.model_json_schema()
        schema.pop("title", None)
        return {"type": "function", "function": {"name": self.name, "description": self.description, "parameters": schema}}

    def validate(self, raw: dict[str, Any]) -> Args:
        return self.args_model.model_validate(raw)


TOOLS: dict[str, ToolSpec] = {t.name: t for t in [
    ToolSpec("create_product", "Propose adding a product with stock to the inventory (or adding quantity to an existing "
             "matching product). Requires user confirmation. Call once per distinct product.",
             CreateProductArgs, "write", preview=preview_create_product, commit=commit_create_product),
    ToolSpec("update_product", "Propose changing an existing product's name, description, category, unit or low-stock threshold.",
             UpdateProductArgs, "write", preview=preview_update_product, commit=commit_update_product),
    ToolSpec("update_inventory", "Propose a stock correction for an existing product that is NOT a sale (received goods, "
             "damage, stock count): a signed change (e.g. -5) or an absolute quantity.",
             UpdateInventoryArgs, "write", preview=preview_update_inventory, commit=commit_update_inventory),
    ToolSpec("update_price", "Propose changing the selling and/or purchase price of an existing product.",
             UpdatePriceArgs, "write", preview=preview_update_price, commit=commit_update_price),
    ToolSpec("record_sale", "Propose recording a sale of an existing product: deducts stock and records revenue. "
             "Use for «satdım/sold». Call once per product sold.",
             RecordSaleArgs, "write", preview=preview_record_sale, commit=commit_record_sale),
    ToolSpec("cancel_sale", "Propose cancelling a recorded sale by its number (S-…). Stock is returned and a traceable "
             "return record is created; nothing is deleted.",
             CancelSaleArgs, "write", preview=preview_cancel_sale, commit=commit_cancel_sale),
    ToolSpec("search_inventory", "Search the inventory by text, stock status, or quantity below a threshold. "
             "Use it to answer «how many X do I have».",
             SearchInventoryArgs, "read", run=run_search_inventory),
    ToolSpec("get_inventory_summary", "Totals for the inventory: product count, units, value at cost, low-stock items.",
             EmptyArgs, "read", run=run_inventory_summary),
    ToolSpec("get_sales_analytics", "Sales analytics from recorded sales and returns over the last N days: summary "
             "(revenue, cost, gross profit), top products by revenue or units, or products that have not sold.",
             SalesAnalyticsArgs, "read", run=run_sales_analytics),
    ToolSpec("get_reorder_suggestions", "Which products to reorder, computed from current stock, minimum thresholds "
             "and sales velocity. Returns the evidence for each suggestion.",
             ReorderArgs, "read", run=run_reorder),
]}


def tool_specs() -> list[ToolSpec]:
    return list(TOOLS.values())


def format_validation_error(exc: ValidationError) -> str:
    return "; ".join(f"{'.'.join(str(x) for x in e['loc']) or 'args'}: {e['msg']}" for e in exc.errors()[:5])
